const csv = `2025-05,15500,3200,4700,23400
2025-06,15500,3200,4700,23400
2025-07,15900,3200,4700,23800
2025-08,15900,3200,4700,23800
2025-09,15900,3200,4700,23800
2025-10,16200,3200,4700,24100
2025-11,16200,3200,4700,24100
2025-12,16200,3200,4700,24100
2026-01,16400,3200,4700,24300
2026-02,16400,3200,4700,24300
2026-03,16200,0,4700,20900
2026-04,16700,3200,4700,24600`;
let ok = true;
let sal=0, pro=0, enc=0, tot=0;
for (const line of csv.split("\n")) {
  const [m,s,p,e,t] = line.split(",").map(x=>parseFloat(x));
  if (s+p+e !== t) { ok=false; console.log("ROW MISMATCH "+m); }
  sal+=s; pro+=p; enc+=e; tot+=t;
}
console.log("rows consistent:", ok, "| salarios", sal, "| prolabore", pro, "| encargos", enc, "| total", tot);
// faturamento
const fat=[78000,81500,84000,86000,79500,90000,88000,92000,85000,83000,86000,87000];
const rbt = fat.reduce((a,b)=>a+b,0);
console.log("RBT12", rbt);
// DAS
const effV = (rbt*0.205-17100)/rbt, effIII = (rbt*0.16-35640)/rbt;
console.log("effV %", effV*100, "effIII %", effIII*100);
const dasServ = 78000*effV, dasLocBruto = 6000*effIII, iss = dasLocBruto*0.325, dasLoc = dasLocBruto-iss;
console.log("dasServ", dasServ, "| loc bruto", dasLocBruto, "| iss", iss, "| loc liq", dasLoc);
console.log("total", dasServ+dasLoc);
// repartição locação
const rep = {IRPJ:0.04, CSLL:0.035, COFINS:0.1405, PIS:0.0305, CPP:0.4275};
const repSum = Object.entries(rep).map(([k,v])=>[k,(dasLocBruto*v).toFixed(2)]).reduce((a,[k,v])=>(a[k]=parseFloat(v),a),{});
console.log("repart locação:", repSum, "soma", Object.values(repSum).reduce((a,b)=>a+b,0).toFixed(2));
console.log("soma % repartição:", (0.04+0.035+0.1405+0.0305+0.4275+0.325).toFixed(4));
// folha variants
console.log("2846-3200 =", 284600-3200, "| fator corrigido", (281400/rbt*100).toFixed(4), "| s/ correção", (284600/rbt*100).toFixed(4), "| corte", 0.28*rbt);
return "audit done";

